#!/usr/bin/env python3
"""Execute actual enrollment JS with bounded fake local API; verify mutation/credential boundaries."""
import sys as _nas_sys
_nas_sys.dont_write_bytecode=True
from pathlib import Path as _NasPath
_nas_sys.path.insert(0,str(_NasPath(__file__).resolve().parents[1]/'scripts'))
import json,subprocess
from pathlib import Path
from js_runner import run_node
root=Path(__file__).resolve().parents[2]
js=(root/'core/web/connect.js').read_text()
harness=r'''
const vm=require('vm'),fs=require('fs'),assert=require('assert/strict');const js=JSON.parse(fs.readFileSync(0,'utf8')).js;
const ctx={URLSearchParams,AbortSignal,window:{},document:{querySelector(){return {textContent:'',value:''}}}};vm.createContext(ctx);vm.runInContext(js+';globalThis.API={LocalSyncthing,enrollLocal,syncPath,detachLocal,renderLocalBinding,renderSyncDetails,percentLabel};',ctx);const {LocalSyncthing,enrollLocal,detachLocal,renderLocalBinding}=ctx.API;
const nas={device_id:'NAS',folder_id:'nas-shared',label:'共享',address:'tcp://nas.example:22000'};let checks=[];
function fixture(opts={}){const calls=[],status={myID:'LOCAL',tilde:'/Users/test',pathSeparator:'/',...opts.status};let folders=structuredClone(opts.folders||[]),devices=[{deviceID:'OTHER',name:'preserve',addresses:['dynamic']}];return {calls,status,get folders(){return folders},async api(p,d,m){calls.push([p,structuredClone(d),m]);if(p==='system/status')return status;if(p==='config/folders'&&d===undefined)return structuredClone(folders);if(p==='config/devices'&&d===undefined)return structuredClone(devices);if(p.startsWith('system/browse?'))return opts.entries||[];if(p==='config/defaults/folder')return {devices:[],filesystemType:'basic'};if(p==='config/defaults/device')return {};if(p==='config/devices'&&d){devices.push(structuredClone(d));return}if(p==='config/folders'&&d){folders.push(structuredClone(d));return}if(p==='config/folders/nas-shared'&&m==='DELETE'){folders=folders.filter(f=>f.id!=='nas-shared');return}if(p==='config/folders/nas-shared'){Object.assign(folders.find(f=>f.id==='nas-shared'),d);return}throw Error('unexpected '+p)}}}
(async()=>{
let f=fixture(),posted=[];await enrollLocal(f,nas,'~/NAS/共享',async d=>{posted.push(d);assert.equal(f.folders[0].paused,true)});assert.equal(f.folders[0].paused,false);assert.equal(f.folders[0].maxConflicts,-1);assert.equal(f.folders[0].versioning.params.keep,'20');assert.equal(posted[0].device,'LOCAL');assert.equal(Object.keys(posted[0]).sort().join(','),'action,device,name');checks.push('fresh local enrollment pauses folder until NAS registration succeeds; private credentials/path excluded from NAS payload');
let before=f.folders.length;await enrollLocal(f,nas,'~/NAS/共享',async()=>{});assert.equal(f.folders.length,before);checks.push('retry of compatible existing folder is idempotent');
f=fixture();await assert.rejects(enrollLocal(f,nas,'~/NAS/共享',async()=>{throw Error('NAS offline')}));assert.equal(f.folders[0].paused,true);await enrollLocal(f,nas,'~/NAS/共享',async()=>{});assert.equal(f.folders[0].paused,false);checks.push('failed NAS action leaves new folder paused and same-page retry resumes safely');
for(const options of [{status:{myID:'NAS'}},{entries:['/Users/test/NAS/共享/']},{folders:[{id:'other',path:'/Users/test/NAS'}]},{folders:[{id:'other',path:'/Users/test/nas'}]},{folders:[{id:'nas-shared',path:'/different',type:'sendreceive'}]},{folders:[{id:'nas-shared',path:'/Users/test/NAS/共享',filesystemType:'basic',type:'sendreceive',devices:[{deviceID:'OTHER'}]}]}]){f=fixture(options);await assert.rejects(enrollLocal(f,nas,'~/NAS/共享',async()=>{}));assert(!f.calls.some(c=>c[1]!==undefined))}checks.push('self enrollment, nonempty targets, overlapping paths and incompatible existing folders reject before writes');
for(const p of ['/','~/','../shared','/Volumes/nas/shared','/mnt/share']){f=fixture();await assert.rejects(enrollLocal(f,nas,p,async()=>{}));assert(!f.calls.some(c=>c[1]!==undefined))}checks.push('root/home/network/relative locations rejected');
f=fixture({status:{tilde:'C:\\Users\\test',pathSeparator:'\\'}});await enrollLocal(f,nas,'~\\NAS\\Shared',async()=>{});assert.equal(f.folders[0].path,'C:\\Users\\test\\NAS\\Shared');checks.push('Windows paths expand using local Syncthing home and separator');
let network=[];ctx.fetch=async(url,options)=>{network.push([url,options]);return {status:200,ok:true,text:async()=>'{"myID":"LOCAL"}'}};let client=new LocalSyncthing(8384,'fixture-private-key');await client.api('system/status');assert(network.every(([url,o])=>url.startsWith('http://127.0.0.1:8384/rest/')&&o.headers['X-API-Key']==='fixture-private-key'&&o.credentials==='omit'&&o.redirect==='error'));assert.throws(()=>new LocalSyncthing('evil.example','key'));checks.push('credentials sent only to fixed loopback origin, without cookies or redirect following');
ctx.Request=class {constructor(url,o){if(o.targetAddressSpace==='loopback')throw new TypeError('unsupported enum')}};ctx.TypeError=TypeError;network=[];await client.api('system/status');assert.equal(network.length,1);assert.equal(network[0][1].targetAddressSpace,'local');checks.push('older browser enum falls back before network request, without retrying writes');
f=fixture();await enrollLocal(f,nas,'~/NAS/共享',async()=>{});await assert.rejects(detachLocal(f,nas,async()=>{throw Error('NAS unavailable')}));assert.equal(f.folders[0].paused,true);assert(!f.calls.some(c=>c[2]==='DELETE'));await detachLocal(f,nas,async data=>{assert.equal(data.action,'sync-unpair');assert.equal(f.folders[0].paused,true)});assert.equal(f.folders.length,0);assert(!f.calls.some(c=>c[0]==='config/devices'&&c[2]==='DELETE'));checks.push('unbind pauses first, preserves config on NAS failure, and deletes only selected folder config after NAS acknowledgment');
const elements={};ctx.document.querySelector=s=>elements[s]??={hidden:false,textContent:'',value:''};renderLocalBinding({path:'/existing'});assert.equal(elements['#local-new'].hidden,true);assert.equal(elements['#local-bound'].hidden,false);assert.equal(elements['#local-current-path'].textContent,'/existing');renderLocalBinding(null);assert.equal(elements['#local-new'].hidden,false);assert.equal(elements['#local-bound'].hidden,true);checks.push('bound UI hides path input/bind button, displays path as text; unbound UI allows new path');
ctx.fixture=fixture({entries:['/Users/test/filled/']});ctx.window.nasConnection=nas;vm.runInContext('localClient=fixture;localStatus=fixture.status;',ctx);ctx.document.querySelector('#local-path').value='/Users/test/filled';await vm.runInContext('connectThisDevice()',ctx);assert.equal(elements['#local-path'].value,'/Users/test/filled');assert.equal(elements['#local-new'].hidden,false);assert(elements['#connect-message'].textContent.includes('已经存在'));assert.equal(elements['#connect-message'].className,'bad');assert(!ctx.fixture.calls.some(c=>c[1]!==undefined));checks.push('nonempty/existing target visibly rejects without resetting input or writing configuration');
function el(tag='div',text=''){return {tag,textContent:text,children:[],append(...x){this.children.push(...x)},replaceChildren(...x){this.children=x}}};const panels={};ctx.document.querySelector=s=>panels[s]??=el();ctx.document.createTextNode=t=>el('text',t);ctx.node=(tag,text)=>el(tag,text);ctx.serviceURL=()=> 'https://files.example/';let sync={mode:'full_sync',sync_state:'idle',completion:100,pending_items:0,peers:[{id:'P',name:'Mac',connected:false,completion:100}],conflicts:[]};ctx.API.renderSyncDetails(sync);let text=n=>n.textContent+' '+n.children.map(text).join(' ');assert(text(panels['#sync-progress']).includes('离线，当前进度未知'));assert(!text(panels['#sync-progress']).includes('已连接，已知进度'));assert.equal(ctx.API.percentLabel(99.99999,1),'99.9%');assert.equal(ctx.API.percentLabel(undefined,0),'未知');checks.push('offline progress never claims completion; pending items cannot round to 100%; unavailable progress remains unknown');
sync.peers=[{id:'P',name:'Mac',connected:true,folder_state:'valid',completion:99.99999,pending_items:1}];sync.conflicts=['nested/file.sync-conflict-20260101-120000-ABCDEF1.txt'];ctx.API.renderSyncDetails(sync);let links=[];function collect(n){if(n.tag==='a')links.push(n);n.children.forEach(collect)}collect(panels['#sync-conflicts']);assert.equal(links.length,2);assert(decodeURIComponent(links[1].href).includes('shared/nested/file.txt'));assert(text(panels['#sync-progress']).includes('99.9%'));checks.push('conflict/current links preserve original filename and peer progress exposes pending item');
console.log(JSON.stringify({state:'PASS',checks,limitations:['Node VM execution with simulated local API; browser CORS/permission and actual Syncthing verified separately']}));
})().catch(e=>{console.error(e.message);process.exit(1)});
'''
report=json.loads(run_node(harness,{'js':js}));(root/'system/runtime/acceptance/connect-js.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS:',len(report['checks']),'browser enrollment behavior checks')
